import hashlib,json,re
from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urlsplit,parse_qs

class Page(HTMLParser):
    def __init__(self):
        super().__init__()
        self.text=[]
        self.links=[]
        self.hidden=0
    def handle_starttag(self,tag,attrs):
        if tag in ('script','style'):
            self.hidden+=1
        if tag=='a':
            href=dict(attrs).get('href') or ''
            if href.lower().startswith('mailto:'):
                fields=parse_qs(urlsplit(href).query)
                subject=' '.join(fields.get('subject',[]))
                body=' '.join(fields.get('body',[]))
                self.links.append({'subject_present':bool(subject),'body_present':bool(body),'experiment_identifiers':sorted(set(re.findall(r'(?:site|experiment):[a-z0-9-]+',subject+' '+body)))})
    def handle_endtag(self,tag):
        if tag in ('script','style') and self.hidden:
            self.hidden-=1
    def handle_data(self,data):
        if not self.hidden and data.strip():
            self.text.append(' '.join(data.split()))

root=Path('products/distribution')
paths=[root/'invoice-checkpoint/2026-11-19-live.html',root/'invoice-preflight-live-r2.html',root/'invoice-preflight-live.html']
report={'sources':[], 'scope':'Public release and buyer intake wording only. Verify the live capture receipt and match the live hash to an authoritative deployment receipt before assigning a cutoff. This check cannot establish requests, replies, orders or settlement.'}
for path in paths:
    if not path.is_file():
        report['sources'].append({'path':str(path),'present':False})
        continue
    raw=path.read_bytes()
    page=Page()
    page.feed(raw.decode('utf-8'))
    excerpt=[text for text in page.text if re.search(r'\b20\b|anonym|synthe|synthé|attach|joint|diagnostic|deadline|expir|clôture|novem|follow.on|customis|personnalis',text,re.I)]
    report['sources'].append({'path':str(path),'present':True,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'intake_and_date_excerpts':excerpt[:25],'mailto_checks':page.links})
out=root/'invoice-checkpoint/2026-11-19-intake-readback.json'
out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(out.read_text(encoding='utf-8'))
